# tsl.nn.layers.base.embedding.py
class NodeEmbedding(nn.Module):
    def __init__(self, n_nodes: int, emb_size: int, initializer: Union[str, Tensor] = 'uniform', requires_grad: bool = True):
        super().__init__()
        self.n_nodes = int(n_nodes)
        self.emb_size = int(emb_size)
        if isinstance(initializer, Tensor):
            self.initializer = "from_values"
            self.register_buffer('_default_values', initializer.float())
        else:
            self.initializer = initializer
            self.register_buffer('_default_values', None)
        self.emb = nn.Parameter(Tensor(self.n_nodes, self.emb_size), requires_grad=requires_grad)
        self.reset_emb()

    def reset_emb(self):
        with torch.no_grad():
            if self.initializer == 'uniform' or self.initializer is None:
                bound = 1.0 / math.sqrt(self.emb.size(-1))
                self.emb.data.uniform_(-bound, bound)
            elif self.initializer == 'from_values':
                self.emb.data.copy_(self._default_values)
            else:
                raise RuntimeError(f"Embedding initializer '{self.initializer}'" " is not supported.")

    def reset_parameters(self): self.reset_emb()
    def get_emb(self): return self.emb

    def forward(self, expand: Optional[List] = None, node_index: OptTensor = None, nodes_first: bool = True):
        emb = self.get_emb()
        if node_index is not None: emb = emb[node_index]
        if not nodes_first: emb = emb.T
        if expand is None: return emb
        shape = [*emb.size()]
        view = [1 if d > 0 else shape.pop(0 if nodes_first else -1) for d in expand]
        return emb.view(*view).expand(*expand)


# tsl.nn.utils.py
_torch_activations_dict = {
    'elu': 'ELU', 'leaky_relu': 'LeakyReLU', 'prelu': 'PReLU', 'relu': 'ReLU', 'rrelu': 'RReLU',
    'selu': 'SELU', 'celu': 'CELU', 'gelu': 'GELU', 'glu': 'GLU', 'mish': 'Mish', 'sigmoid': 'Sigmoid',
    'softplus': 'Softplus', 'tanh': 'Tanh', 'silu': 'SiLU', 'swish': 'SiLU', 'linear': 'Identity'
}

def _identity(x): return x

def get_functional_activation(activation: Optional[str] = None):
    if activation is None: return _identity
    activation = activation.lower()
    if activation == 'linear': return _identity
    if activation in ['tanh', 'sigmoid']: return getattr(torch, activation)
    if activation in _torch_activations_dict: return getattr(F, activation)
    raise ValueError(f"Activation '{activation}' not valid.")

def get_layer_activation(activation: Optional[str] = None):
    if activation is None: return nn.Identity
    activation = activation.lower()
    if activation in _torch_activations_dict: return getattr(nn, _torch_activations_dict[activation])
    raise ValueError(f"Activation '{activation}' not valid.")

def maybe_cat_exog(x, u, dim=-1):
    if u is not None:
        if u.dim() == 3: u = rearrange(u, 'b s f -> b s 1 f')
        x = torch.cat([x, u], dim)
    return x

def maybe_cat_emb(x: Tensor, emb: Optional[Tensor]):
    if emb is None: return x
    if emb.ndim < x.ndim:
        if emb.ndim == 3 and x.ndim == 4: emb = emb.unsqueeze(1)
        else: emb = emb[[None] * (x.ndim - emb.ndim)]
    emb = emb.expand(*x.shape[:-1], -1)
    return torch.cat([x, emb], dim=-1)


# tsl.nn.functional.py (only gated_tanh, sparse_softmax)
@torch.jit.script
def gated_tanh(input: Tensor, dim: int = -1) -> Tensor:
    out, gate = torch.tensor_split(input, 2, dim=dim)
    return torch.tanh(out) * torch.sigmoid(gate)

@torch.jit.script
def sparse_softmax(src: Tensor, index: Optional[Tensor] = None, ptr: Optional[Tensor] = None, num_nodes: Optional[int] = None, dim: int = -2) -> Tensor:
    if ptr is not None:
        dim = dim + src.dim() if dim < 0 else dim
        size = ([1] * dim) + [-1]
        ptr = ptr.view(size)
        src_max = torch_scatter.gather_csr(torch_scatter.segment_csr(src, ptr, reduce='max'), ptr)
        out = (src - src_max).exp()
        out_sum = torch_scatter.gather_csr(torch_scatter.segment_csr(out, ptr, reduce='sum'), ptr)
    elif index is not None:
        N = maybe_num_nodes(index, num_nodes)
        expanded_index = torch_scatter.utils.broadcast(index, src, dim)
        src_max = torch_scatter.scatter(src, expanded_index, dim, dim_size=N, reduce='max')
        src_max = src_max.index_select(dim, index)
        out = (src - src_max).exp()
        out_sum = torch_scatter.scatter(out, expanded_index, dim, dim_size=N, reduce='sum')
        out_sum = out_sum.index_select(dim, index)
    else: raise NotImplementedError
    return out / (out_sum + epsilon)


# tsl.nn.layers.base.dense.py
class Dense(nn.Module):
    def __init__(self, input_size: int, output_size: int, activation: str = 'relu', dropout: float = 0., bias: bool = True):
        super().__init__()
        self.affinity = nn.Linear(input_size, output_size, bias=bias)
        self.activation = get_layer_activation(activation)()
        self.dropout = nn.Dropout(dropout) if dropout > 0. else nn.Identity()
    def forward(self, x): return self.dropout(self.activation(self.affinity(x)))


# tsl.nn.blocks.encoders.mlp.py (MLP and ResidualMLP)
class MLP(nn.Module):
    def __init__(self, input_size, hidden_size, output_size=None, exog_size=None, n_layers=1, activation='relu', dropout=0.):
        super().__init__()
        if exog_size is not None: input_size += exog_size
        layers = [Dense(input_size=input_size if i == 0 else hidden_size, output_size=hidden_size, activation=activation, dropout=dropout) for i in range(n_layers)]
        self.mlp = nn.Sequential(*layers)
        if output_size is not None: self.readout = nn.Linear(hidden_size, output_size)
        else: self.register_parameter('readout', None)

    def forward(self, x, u=None):
        x = maybe_cat_exog(x, u)
        out = self.mlp(x)
        if self.readout is not None: return self.readout(out)
        return out

class ResidualMLP(nn.Module):
    def __init__(self, input_size, hidden_size, output_size=None, exog_size=None, n_layers=1, activation='relu', dropout=0., parametrized_skip=False):
        super().__init__()
        if exog_size is not None: input_size += exog_size
        self.layers = nn.ModuleList([
            nn.Sequential(Dense(input_size=input_size if i == 0 else hidden_size, output_size=hidden_size, activation=activation, dropout=dropout), nn.Linear(hidden_size, hidden_size))
            for i in range(n_layers)
        ])
        self.skip_connections = nn.ModuleList()
        for i in range(n_layers):
            if i == 0 and input_size != hidden_size: self.skip_connections.append(nn.Linear(input_size, hidden_size))
            elif parametrized_skip: self.skip_connections.append(nn.Linear(hidden_size, hidden_size))
            else: self.skip_connections.append(nn.Identity())
        if output_size is not None: self.readout = nn.Linear(hidden_size, output_size)
        else: self.register_parameter('readout', None)

    def forward(self, x, u=None):
        x = maybe_cat_exog(x, u)
        for layer, skip in zip(self.layers, self.skip_connections): x = layer(x) + skip(x)
        if self.readout is not None: return self.readout(x)
        return x


# tsl.nn.blocks.encoders.recurrent.base.py
# (Only minimal definitions needed for RNN and its cells)
class RNNCellBase(nn.Module):
    def initialize_state(self, *args, **kwargs) -> Any: raise NotImplementedError

class GRUCellBase(RNNCellBase):
    def __init__(self, hidden_size: int, forget_gate: nn.Module, update_gate: nn.Module, candidate_gate: nn.Module):
        super().__init__()
        self.hidden_size = hidden_size
        self.forget_gate = forget_gate
        self.update_gate = update_gate
        self.candidate_gate = candidate_gate
    def reset_parameters(self):
        self.forget_gate.reset_parameters()
        self.update_gate.reset_parameters()
        self.candidate_gate.reset_parameters()
    def initialize_state(self, x) -> Tensor: return torch.zeros(x.size(0), self.hidden_size, dtype=x.dtype, device=x.device)
    def forward(self, x: Tensor, h: Tensor, *args, **kwargs) -> Tensor:
        x_gates = torch.cat([x, h], dim=-1)
        r = torch.sigmoid(self.forget_gate(x_gates, *args, **kwargs))
        u = torch.sigmoid(self.update_gate(x_gates, *args, **kwargs))
        x_c = torch.cat([x, r * h], dim=-1)
        c = torch.tanh(self.candidate_gate(x_c, *args, **kwargs))
        h_new = u * h + (1. - u) * c
        return h_new

class LSTMCellBase(RNNCellBase):
    def __init__(self, hidden_size: int, input_gate: nn.Module, forget_gate: nn.Module, cell_gate: nn.Module, output_gate: nn.Module):
        super().__init__()
        self.hidden_size = hidden_size
        self.input_gate = input_gate
        self.forget_gate = forget_gate
        self.cell_gate = cell_gate
        self.output_gate = output_gate
    def reset_parameters(self):
        self.input_gate.reset_parameters()
        self.forget_gate.reset_parameters()
        self.cell_gate.reset_parameters()
        self.output_gate.reset_parameters()
    def initialize_state(self, x) -> Tuple[Tensor, Tensor]: return (torch.zeros(x.size(0), self.hidden_size, dtype=x.dtype, device=x.device), torch.zeros(x.size(0), self.hidden_size, dtype=x.dtype, device=x.device))
    def forward(self, x: Tensor, hc: Tuple[Tensor, Tensor], *args, **kwargs) -> Tuple[Tensor, Tensor]:
        h, c = hc
        x_gates = torch.cat([x, h], dim=-1)
        i = torch.sigmoid(self.input_gate(x_gates, *args, **kwargs))
        f = torch.sigmoid(self.forget_gate(x_gates, *args, **kwargs))
        g = torch.tanh(self.cell_gate(x_gates, *args, **kwargs))
        o = torch.sigmoid(self.output_gate(x_gates, *args, **kwargs))
        c_new = f * c + i * g
        h_new = o * torch.tanh(c_new)
        return h_new, c_new


# tsl.nn.blocks.encoders.recurrent.rnn.py (RNN only)
class RNN(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, exog_size: int = None, output_size: int = None, n_layers: int = 1, return_only_last_state: bool = False, cell: str = 'gru', bias: bool = True, dropout: float = 0., **kwargs):
        super().__init__()
        self.return_only_last_state = return_only_last_state
        if cell == 'gru': cell = nn.GRU
        elif cell == 'lstm': cell = nn.LSTM
        else: raise NotImplementedError(f'"{cell}" cell not implemented.')
        if exog_size is not None: input_size += exog_size
        self.rnn = cell(input_size=input_size, hidden_size=hidden_size, num_layers=n_layers, bias=bias, dropout=dropout)
        if output_size is not None: self.readout = nn.Linear(hidden_size, output_size)
        else: self.register_parameter('readout', None)

    def forward(self, x: Tensor, u: Optional[Tensor] = None):
        x = maybe_cat_exog(x, u)
        b, *_ = x.size()
        x = rearrange(x, 'b s n f -> s (b n) f')
        x, *_ = self.rnn(x)
        x = rearrange(x, 's (b n) f -> b s n f', b=b)
        if self.return_only_last_state: x = x[:, -1]
        if self.readout is not None: return self.readout(x)
        return x


# tsl.nn.blocks.decoders.mlp_decoder.py
class MLP(nn.Module):
    def __init__(self, input_size, hidden_size, output_size=None, exog_size=None, n_layers=1, activation='relu', dropout=0.):
        super().__init__()
        if exog_size is not None: input_size += exog_size
        layers = [Dense(input_size=input_size if i == 0 else hidden_size, output_size=hidden_size, activation=activation, dropout=dropout) for i in range(n_layers)]
        self.mlp = nn.Sequential(*layers)
        if output_size is not None: self.readout = nn.Linear(hidden_size, output_size)
        else: self.register_parameter('readout', None)
    def forward(self, x, u=None):
        x = maybe_cat_exog(x, u)
        out = self.mlp(x)
        if self.readout is not None: return self.readout(out)
        return out

class MLPDecoder(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int, horizon: int = 1, n_layers: int = 1, receptive_field: int = 1, activation: str = 'relu', dropout: float = 0.):
        super().__init__()
        self.receptive_field = receptive_field
        self.readout = MLP(input_size=receptive_field * input_size, hidden_size=hidden_size, output_size=output_size * horizon, n_layers=n_layers, dropout=dropout, activation=activation)
        self.rearrange = nn.Sequential(nn.Identity(), lambda out: rearrange(out, 'b n (h f) -> b h n f', f=output_size, h=horizon))

    def forward(self, h):
        if h.dim() == 4: h = rearrange(h[:, -self.receptive_field:], 'b t n f -> b n (t f)')
        else: assert self.receptive_field == 1
        out = self.readout(h)
        return self.rearrange(out)


# tsl.ops.connectivity.py (minimal functions used by GraphConv, DiffConv, HierarchyBuilder)
def maybe_num_nodes(edge_index, num_nodes=None): return int(edge_index.max()) + 1 if edge_index.numel() > 0 else 0
def infer_backend(obj, backend: Type[torch] = None): return torch # simplified for torch-only
def transpose(edge_index: Adj, edge_weights: OptTensor = None): return edge_index[[1, 0]], edge_weights

def weighted_degree(index: Tensor, weights: OptTensor = None, num_nodes: Optional[int] = None) -> Tensor:
    N = maybe_num_nodes(index, num_nodes)
    if weights is None: weights = torch.ones((index.size(0), ), device=index.device, dtype=torch.int)
    out = torch.zeros((N, ), dtype=weights.dtype, device=weights.device)
    out.scatter_add_(0, index, weights)
    return out

def asymmetric_norm(edge_index: Adj, edge_weight: OptTensor = None, dim: int = 0, num_nodes: Optional[int] = None, add_self_loops: bool = False) -> Tuple[Adj, OptTensor]:
    # simplified assuming edge_index is Tensor
    if add_self_loops: edge_index, tmp_edge_weight = add_remaining_self_loops(edge_index, edge_weight, 1, num_nodes); assert tmp_edge_weight is not None; edge_weight = tmp_edge_weight
    index = edge_index[dim]
    degree = weighted_degree(index, edge_weight, num_nodes=num_nodes)
    norm_weight = (1 if edge_weight is None else edge_weight) / (degree[index] + epsilon)
    return edge_index, norm_weight

def normalize_connectivity(edge_index, edge_weight, norm, num_nodes) -> Tuple[Adj, OptTensor]:
    if norm == 'sym': return gcn_norm(edge_index, edge_weight, num_nodes, add_self_loops=False)
    elif (norm == 'asym') or (norm == 'mean'): return asymmetric_norm(edge_index, edge_weight, dim=1, num_nodes=num_nodes, add_self_loops=False)
    elif norm == 'gcn': return gcn_norm(edge_index, edge_weight, num_nodes, add_self_loops=True)
    elif (norm == 'none') or (norm is None):
        if (edge_weight is None): edge_weight = torch.ones((edge_index.size(1), ), device=edge_index.device)
        return edge_index, edge_weight
    else: raise NotImplementedError(f'Normalization {norm} not implemented.')


# tsl.nn.layers.graph_convs.mixin.py
class NormalizedAdjacencyMixin:
    _cached_edge_index: Optional[Tuple[Tensor, Tensor]] = None
    cached: bool = False
    norm: str = 'none'
    def normalize_edge_index(self, x, edge_index, edge_weight, use_cached):
        if use_cached:
            if self._cached_edge_index is None: return self.normalize_edge_index(x, edge_index, edge_weight, False)
            return self._cached_edge_index
        edge_index, edge_weight = normalize_connectivity(edge_index, edge_weight, norm=self.norm, num_nodes=x.size(-2))
        if self.cached: self._cached_edge_index = (edge_index, edge_weight)
        return edge_index, edge_weight


# tsl.nn.layers.graph_convs.graph_conv.py
class GraphConv(MessagePassing, NormalizedAdjacencyMixin):
    def __init__(self, input_size: int, output_size: int, bias: bool = True, norm: str = 'mean', root_weight: bool = True, activation: str = None, cached: bool = False):
        super().__init__(aggr="add", node_dim=-2)
        self.in_channels = input_size; self.out_channels = output_size; self.norm = norm; self.cached = cached
        self.activation = get_functional_activation(activation)
        self.lin = nn.Linear(input_size, output_size, bias=False)
        if root_weight: self.root_lin = nn.Linear(input_size, output_size, bias=False)
        else: self.register_parameter('root_lin', None)
        if bias: self.bias = Parameter(torch.Tensor(output_size))
        else: self.register_parameter('bias', None)
        self.reset_parameters()
    def reset_parameters(self):
        self.lin.reset_parameters();
        if self.root_lin is not None: self.root_lin.reset_parameters();
        if self.bias is not None: torch.nn.init.zeros_(self.bias)
    def forward(self, x: Tensor, edge_index: Adj, edge_weight: OptTensor = None) -> Tensor:
        out = self.lin(x)
        edge_index, edge_weight = self.normalize_edge_index(x, edge_index=edge_index, edge_weight=edge_weight, use_cached=self.cached)
        out = self.propagate(edge_index, x=out, edge_weight=edge_weight)
        if self.root_lin is not None: out += self.root_lin(x)
        if self.bias is not None: out += self.bias
        return self.activation(out)
    def message(self, x_j: Tensor, edge_weight) -> Tensor: return edge_weight.view(-1, 1) * x_j
    def message_and_aggregate(self, adj_t: SparseTensor, x: Tensor) -> Tensor: return matmul(adj_t, x, reduce=self.aggr)


# lib.nn.layers.graph_aniso_conv.py
class Activation(nn.Module):
    def __init__(self, activation: str, **kwargs): super().__init__(); self.activation: nn.Module = get_layer_activation(activation)(**kwargs)
    def forward(self, x): return self.activation(x)

class GraphAnisoConv(MessagePassing):
    def __init__(self, input_size: int, output_size: int, edge_dim: Optional[int] = None, activation: str = 'leaky_relu'):
        super().__init__(aggr="add", node_dim=-2)
        self.in_channels = input_size; self.out_channels = output_size
        self.msg_mlp = nn.Sequential(nn.Linear(2 * input_size, output_size), Activation(activation), nn.Linear(output_size, output_size))
        edge_dim = edge_dim or 0
        if edge_dim > 0: self.lin_edge = nn.Linear(edge_dim, output_size)
        else: self.register_parameter('lin_edge', None)
        self.gate_mlp = Dense(output_size, 1, activation='sigmoid')
        self.skip_conn = nn.Linear(input_size, output_size)
        self.activation = Activation(activation)
    def forward(self, x, edge_index, edge_attr: Optional[Tensor] = None):
        if edge_attr is not None: 
            if edge_attr.ndim == 1: edge_attr = edge_attr.view(-1, 1)
            edge_attr = self.lin_edge(edge_attr)
        out = self.propagate(edge_index, x=x, edge_attr=edge_attr)
        out = self.activation(out + self.skip_conn(x))
        return out
    def message(self, x_i, x_j, edge_attr):
        mij = self.msg_mlp(torch.cat([x_i, x_j], -1))
        if edge_attr is not None: mij = mij + edge_attr
        return self.gate_mlp(mij) * mij


# tsl.nn.layers.graph_convs.diff_conv.py
class DiffConv(MessagePassing):
    def __init__(self, in_channels: int, out_channels: int, k: int, root_weight: bool = True, add_backward: bool = True, bias: bool = True, activation: str = None):
        super().__init__(aggr="add", node_dim=-2)
        self.in_channels = in_channels; self.out_channels = out_channels; self.k = k
        self.root_weight = root_weight; self.add_backward = add_backward
        self.activation = get_functional_activation(activation)
        n_filters = k; 
        if add_backward: n_filters *= 2
        if root_weight: n_filters += 1
        self.filters = nn.Linear(in_channels * n_filters, out_channels, bias=bias)
        self._support = None
        self.reset_parameters()

    @staticmethod
    def compute_support_index(edge_index: Adj, edge_weight: OptTensor = None, num_nodes: int = None, add_backward: bool = True) -> List:
        norm_edge_index, norm_edge_weight = asymmetric_norm(edge_index, edge_weight, dim=1, num_nodes=num_nodes)
        if add_backward: return [(norm_edge_index, norm_edge_weight)] + DiffConv.compute_support_index(transpose(edge_index, edge_weight), num_nodes=num_nodes, add_backward=False)
        return [(norm_edge_index, norm_edge_weight)]

    def reset_parameters(self): self.filters.reset_parameters(); self._support = None
    def message(self, x_j: Tensor, weight: Tensor) -> Tensor: return weight.view(-1, 1) * x_j
    def message_and_aggregate(self, adj_t: SparseTensor, x: Tensor) -> Tensor: return matmul(adj_t, x, reduce=self.aggr)

    def forward(self, x: Tensor, edge_index: Adj, edge_weight: OptTensor = None, cache_support: bool = False) -> Tensor:
        n = x.size(-2)
        if self._support is None:
            support = self.compute_support_index(edge_index, edge_weight, add_backward=self.add_backward, num_nodes=n)
            if cache_support: self._support = support
        else: support = self._support
        out = [];
        if self.root_weight: out += [x]
        for sup_index, sup_weights in support:
            x_sup = x
            for _ in range(self.k):
                x_sup = self.propagate(sup_index, x=x_sup, weight=sup_weights)
                out += [x_sup]
        out = torch.cat(out, -1)
        return self.activation(self.filters(out))


# lib.nn.base.time_then_space_model.py
class TimeThenSpaceModel(BaseModel):
    return_type = torch.Tensor

    def __init__(self, input_size: int, horizon: int, n_nodes: int, hidden_size: int, emb_size: int, temporal_layers: int, ff_size: int = None, rnn_size: int = None, skip_connection: bool = False, output_size: int = None, exog_size: int = 0, activation: str = 'elu'):
        super().__init__()
        self.input_size = input_size; self.output_size = output_size or input_size; self.horizon = horizon; self.skip_connection = skip_connection
        self.emb = NodeEmbedding(n_nodes=n_nodes, emb_size=emb_size)
        rnn_size = rnn_size or hidden_size
        self.input_encoder = nn.Linear(input_size + exog_size + emb_size, rnn_size)
        self.temporal_encoder = RNN(input_size=rnn_size if rnn_size != hidden_size else hidden_size, hidden_size=hidden_size if rnn_size != hidden_size else hidden_size, output_size=hidden_size if rnn_size != hidden_size else None, return_only_last_state=True, n_layers=temporal_layers)
        decoder_input_size = hidden_size + emb_size
        if skip_connection: decoder_input_size += rnn_size
        ff_size = ff_size or hidden_size
        self.decoder = MLPDecoder(input_size=decoder_input_size, output_size=self.output_size, horizon=horizon, hidden_size=ff_size, activation=activation)

